-- Elevation: tiled windows rest at level 0 (no shadow), floating windows at level 3.
hl.window_rule({ name = "m3-tiled-level0", match = { float = false }, no_shadow = true })

-- Not M3 (the spec exception shell.translucency): the bar and its flyouts are translucent over a blurred backdrop.
hl.layer_rule({ name = "m3-translucency", match = { namespace = "^omarchy-(bar|osd|keyboard-panel)$" }, enabled = true, blur = true, blur_popups = true, ignore_alpha = 0.84 })

-- Material 3 "standard" springs (md.sys.motion.spring.*), mass 1.
-- Hyprland takes the damping coefficient: 2 * ratio * sqrt(stiffness).
hl.curve("m3_spatial_fast", { type = "spring", mass = 1, stiffness = 1400, dampening = 67.35 })
hl.curve("m3_spatial_default", { type = "spring", mass = 1, stiffness = 700, dampening = 47.624 })
hl.curve("m3_spatial_slow", { type = "spring", mass = 1, stiffness = 300, dampening = 31.177 })
hl.curve("m3_effects_fast", { type = "spring", mass = 1, stiffness = 3800, dampening = 123.288 })
hl.curve("m3_effects_default", { type = "spring", mass = 1, stiffness = 1600, dampening = 80 })
hl.curve("m3_effects_slow", { type = "spring", mass = 1, stiffness = 800, dampening = 56.569 })

hl.animation({ leaf = "global", enabled = true, speed = 1, spring = "m3_effects_default" })
hl.animation({ leaf = "windows", enabled = true, speed = 1, spring = "m3_spatial_default" })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 1, spring = "m3_spatial_default", style = "popin 87%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 1, spring = "m3_spatial_default", style = "popin 87%" })
hl.animation({ leaf = "border", enabled = true, speed = 1, spring = "m3_effects_fast" })
hl.animation({ leaf = "fade", enabled = true, speed = 1, spring = "m3_effects_default" })
hl.animation({ leaf = "layers", enabled = true, speed = 1, spring = "m3_spatial_fast" })
hl.animation({ leaf = "layersIn", enabled = true, speed = 1, spring = "m3_spatial_fast", style = "fade" })
hl.animation({ leaf = "layersOut", enabled = true, speed = 1, spring = "m3_spatial_fast", style = "fade" })
hl.animation({ leaf = "fadeLayersIn", enabled = true, speed = 1, spring = "m3_effects_fast" })
hl.animation({ leaf = "fadeLayersOut", enabled = true, speed = 1, spring = "m3_effects_fast" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 1, spring = "m3_spatial_slow", style = "slide" })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = 1, spring = "m3_spatial_slow", style = "slidevert" })

